<?php
declare(strict_types=1);defined('_JEXEC')or die;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;?>
<?php if(isset($personnel['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($personnel['error']);?></div><?php else:?><div><?php if((bool)$params->get('show_project_name',1)):?><div class="fw-semibold mb-2"><?php echo htmlspecialchars((string)$personnel['project']->name,ENT_QUOTES,'UTF-8');?></div><?php endif;?><?php if($personnel['groups']['staff']===[]&&$personnel['groups']['official']===[]):?><div class="alert alert-info mb-0"><?php echo Text::_('COM_JOOMLEAGUE_PERSONNEL_EMPTY');?></div><?php endif;?><?php foreach(['staff','official']as$group):if($personnel['groups'][$group]===[])continue;?><h3 class="h6 mt-3"><?php echo Text::_('COM_JOOMLEAGUE_PERSONNEL_GROUP_'.strtoupper($group));?></h3><div class="list-group"><?php foreach($personnel['groups'][$group]as$person):?><a class="list-group-item list-group-item-action d-flex gap-3 align-items-center" href="<?php echo Route::_('index.php?option=com_joomleague&view=person&person_id='.(int)$person->person_id);?>"><?php if((bool)$params->get('show_images',1)&&$person->picture):?><img src="<?php echo htmlspecialchars((string)$person->picture,ENT_QUOTES,'UTF-8');?>" alt="" width="48" height="48" class="img-fluid" loading="lazy"><?php else:?><span class="icon-user fs-4 text-body-secondary" aria-hidden="true"></span><?php endif;?><span class="flex-grow-1"><strong class="d-block"><?php echo htmlspecialchars((string)$person->name,ENT_QUOTES,'UTF-8');?></strong><small class="text-body-secondary"><?php echo $person->role_label!==''?Text::_($person->role_label):htmlspecialchars((string)$person->role_code,ENT_QUOTES,'UTF-8');?></small></span><?php if((bool)$params->get('show_counts',1)):?><span class="badge text-bg-light border"><?php echo(int)($group==='staff'?$person->entry_count:$person->assignment_count);?></span><?php endif;?></a><?php endforeach;?></div><?php endforeach;?></div><?php endif;?>
